function showMapping(spec){const [k,sourceAC,targetUnit,targetAC]=spec.split('|'),a=getDraft(),course=assessmentCourse(a),mappingTable=courseMappings(course),m=mappingTable.find(x=>x.sourceUnit===a.primaryUnit&&x.sourceAC===sourceAC&&x.targetUnit===targetUnit&&x.targetAC===targetAC),saved=a.mappings[k].find(x=>x.sourceAC===sourceAC&&x.targetUnit===targetUnit&&x.targetAC===targetAC),source=flattenCourse(course).find(x=>x.unit.id===a.primaryUnit&&x.ac.id===sourceAC),target=flattenCourse(course).find(x=>x.unit.id===targetUnit&&x.ac.id===targetAC),automatic=m.mappingType==='automatic'||saved?.decision==='confirmed';openSheet(`<small>${automatic?'MAPPING DETAIL':'POSSIBLE HOLISTIC MATCH'}</small><h2 id=sheet-title>${targetUnit}-AC${targetAC}</h2><section class=wording-block><small>PRIMARY AC</small><strong>${a.primaryUnit}-AC${sourceAC}</strong><p>${esc(source.ac.wording)}</p></section><section class=wording-block><small>POSSIBLE MATCH</small><strong>${targetUnit}-AC${targetAC}</strong><p>${esc(target.ac.wording)}</p></section><p><strong>Similarity:</strong> ${Math.round(m.similarity*100)}%<br><strong>Status:</strong> ${m.mappingType==='automatic'?'Automatically mapped':saved?.decision==='confirmed'?'Assessor-confirmed holistic match':'Assessor decision required'}</p>${automatic?`<button class=secondary data-close-sheet>Close</button>`:`<div class=button-row><button class="secondary danger" data-sheet-decision="${spec}|ignored">Ignore</button><button class=action data-sheet-decision="${spec}|confirmed">Confirm</button></div>`}`)}
