async function prepareRestore(file){if(!file)return;try{pendingRestore=await validateBackup(file);const {manifest,summary}=pendingRestore;openSheet(`<small>ASSESSOR+ BACKUP</small><h2 id=sheet-title>Restore Summary</h2><p><strong>Created:</strong> ${new Intl.DateTimeFormat('en-GB',{dateStyle:'long',timeStyle:'short'}).format(new Date(manifest.createdAt))}<br><strong>Assessor+ version:</strong> V${esc(manifest.applicationVersion)}</p><p>${summary.activeLearners} active learners<br>${summary.withdrawnLearners} withdrawn learners<br>${summary.reviews} reviews<br>${summary.observations} observations<br>${summary.planningVisits} planned visits<br>${summary.mediaFiles} evidence/media files</p><p><strong>Restoring this backup will replace the Assessor+ data currently stored on this device.</strong></p><div class=button-row><button class=secondary data-close-sheet>Cancel</button><button class="action confirm-danger" data-confirm-restore>Replace Current Data</button></div>`)}catch(error){pendingRestore=null;openSheet(`<h2 id=sheet-title>Backup cannot be restored</h2><p>${esc(error.message)}</p><button class=secondary data-close-sheet>Close</button>`)}}
async function performRestore(){if(!pendingRestore)return;try{await replaceStores(pendingRestore.data);pendingRestore=null;closeSheet();await refresh();assessorProfile={...assessorProfile,...(await get('settings','assessor-profile')||{})};backupSettings={...backupSettings,...(await get('settings','backup-settings')||{})};professionalDocuments=await all('professionalDocuments');render();toast('Backup restored successfully')}catch(error){console.error(error);toast(`Restore failed: ${error.message}`)}}
async function showBackupReminder(){if(reminderShown||!assessorProfile.onboardingComplete||!reminderDue({frequency:backupSettings.reminderFrequency,lastSuccessfulBackup:backupSettings.lastSuccessfulBackup,reminderStartedAt:backupSettings.reminderStartedAt,snoozedAt:backupSettings.snoozedAt}))return;reminderShown=true;const days=backupSettings.lastSuccessfulBackup?Math.floor((Date.now()-Date.parse(backupSettings.lastSuccessfulBackup))/86400000):null;openSheet(`<small>BACKUP RECOMMENDED</small><h2 id=sheet-title>Protect your Assessor+ data</h2><p>${days===null?'It is time to create your first complete backup.':`Your last Assessor+ backup was ${days} days ago.`}</p><div class=button-row><button class=secondary data-snooze-backup>Remind Me Later</button><button class=action data-backup-now>Back Up Now</button></div>`) }
async function generatePdf(id){const a=assessments.find(x=>x.id===id),learner=learners.find(x=>x.id===a.learnerId),course=learnerCourse(learner),safe=filterAssessmentToActiveUnits(a,course,learner);toast('Preparing evidence PDF…');const blob=await makeProfessionalPdf(safe,learner,course,{profile:assessorProfile,assetResolver:(store,key)=>get(store,key)}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=pdfFilename(a,learner);link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('PDF generated')}
async function generateEvidenceZip(id){const a=assessments.find(x=>x.id===id);if(!a)return;const learner=learners.find(x=>x.id===a.learnerId),course=learnerCourse(learner),safe=filterAssessmentToActiveUnits(a,course,learner);toast('Preparing evidence ZIP…');const named=evidenceExportFiles(safe),files=[];for(const item of named){const record=await get('media',item.meta.id);if(record?.blob)files.push({name:item.name,data:record.blob})}const pdf=await makeProfessionalPdf(safe,learner,course,{profile:assessorProfile,embedAttachments:false,assetResolver:(store,key)=>get(store,key)});files.unshift({name:pdfFilename(safe),data:pdf});const blob=await createZip(files),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=zipFilename(safe,course);link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Evidence ZIP downloaded')}
async function requestPdf(id){const a=assessments.find(x=>x.id===id),records=await Promise.all([...(a.media||[]),...(a.knowledgeEvidence||[])].filter(x=>x.kind!=='photo').map(x=>get('media',x.id))),size=records.reduce((n,r)=>n+(r?.blob?.size||0),0);if(size>50*1024*1024){openSheet(`<h2 id=sheet-title>Large evidence PDF</h2><p>This assessment contains ${Math.round(size/1024/1024)} MB of video/audio evidence. The generated PDF will be large.</p><div class=button-row><button class=action data-full-pdf="${id}">Generate Full PDF</button><button class=secondary data-close-sheet>Cancel</button></div>`);return}await generatePdf(id)}
document.addEventListener('submit',async e=>{if(e.target.id==='visit-form'){e.preventDefault();const f=new FormData(e.target),existing=visits.find(v=>v.id===e.target.dataset.visitId),record={...(existing||{}),id:existing?.id||crypto.randomUUID(),learnerId:e.target.dataset.learnerId,date:parseUKDate(f.get('date')),time:f.get('time'),type:f.get('type'),location:f.get('location').trim(),note:f.get('note').trim(),status:existing?.status||'planned',updatedAt:new Date().toISOString()};await put('visits',record);await refresh();closeSheet();render();toast('Visit saved');return}if(e.target.id==='workplace-form'){e.preventDefault();const l=learners.find(x=>x.id===e.target.dataset.learnerId);l.workplace=new FormData(e.target).get('workplace').trim();await put('learners',l);await refresh();closeSheet();render();toast('Workplace saved');return}if(e.target.id==='document-form'){e.preventDefault();if(await saveProfessionalDocument(e.target)){closeSheet();render();toast('Document stored locally')}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet();const panel=$('#sheet:not([hidden]) .sheet-panel');if(e.key==='Tab'&&panel){const focus=[...panel.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')];if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function showStartupError(error){console.error('Assessor+ startup failed.',error);$('#app').innerHTML='<section class="card startup-error" role="alert"><h1>Assessor+ could not finish loading.</h1><p>Your locally stored data has not been changed. If another Assessor+ window is open, close it before retrying.</p><button class="action" id="retry-startup">Retry</button></section>';$('#retry-startup').onclick=()=>{document.body.classList.remove('onboarding-open','assessment-open');$('#app').innerHTML='<section class="card"><p>Loading Assessor+…</p></section>';init().catch(showStartupError)}}
init().catch(showStartupError);
